<?php
require 'partials.php';$uid=require_login();$quizId=(int)($_GET['quiz']??0);
$s=db()->prepare('SELECT id,title FROM jolt_quizzes WHERE id=? AND user_id=?');$s->bind_param('ii',$quizId,$uid);$s->execute();$quiz=$s->get_result()->fetch_assoc();if(!$quiz){http_response_code(404);exit('Jolten hittades inte.');}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$gameId=(int)($_POST['game_id']??0);$action=$_POST['action']??'';if($action==='rename_session'){$name=trim(mb_substr($_POST['name']??'',0,140));$name=$name!==''?$name:null;$s=db()->prepare('UPDATE jolt_games SET name=? WHERE id=? AND quiz_id=? AND host_user_id=?');$s->bind_param('siii',$name,$gameId,$quizId,$uid);$s->execute();}elseif($action==='delete_session'){$s=db()->prepare('DELETE FROM jolt_games WHERE id=? AND quiz_id=? AND host_user_id=?');$s->bind_param('iii',$gameId,$quizId,$uid);$s->execute();}redirect('results.php?quiz='.$quizId);}
$s=db()->prepare('SELECT g.id,g.name,g.created_at,g.status,COUNT(p.id) players FROM jolt_games g LEFT JOIN jolt_players p ON p.game_id=g.id WHERE g.quiz_id=? AND g.host_user_id=? GROUP BY g.id ORDER BY g.created_at DESC');$s->bind_param('ii',$quizId,$uid);$s->execute();$games=$s->get_result()->fetch_all(MYSQLI_ASSOC);
$requested=(int)($_GET['game']??0);$selected=null;foreach($games as $game){if(($requested&&$requested===(int)$game['id'])||(!$requested&&!$selected)){$selected=$game;if($requested)break;}}
$questions=[];$players=[];$points=[];
if($selected){$gameId=(int)$selected['id'];$s=db()->prepare('SELECT question_id,position,text,max_points FROM jolt_game_questions WHERE game_id=? ORDER BY position');$s->bind_param('i',$gameId);$s->execute();$questions=$s->get_result()->fetch_all(MYSQLI_ASSOC);$s=db()->prepare('SELECT id,name,score FROM jolt_players WHERE game_id=? ORDER BY score DESC,joined_at');$s->bind_param('i',$gameId);$s->execute();$players=$s->get_result()->fetch_all(MYSQLI_ASSOC);$s=db()->prepare('SELECT player_id,question_id,points_awarded FROM jolt_responses WHERE game_id=?');$s->bind_param('i',$gameId);$s->execute();$responses=$s->get_result();while($r=$responses->fetch_assoc())$points[(int)$r['player_id']][(int)$r['question_id']]=(int)$r['points_awarded'];}
function result_date(string $date):string{return date('Y-m-d H:i',strtotime($date));}
page_top('Resultat');?>
<header class="page-head"><div><a href="dashboard.php">← Mina Jolt</a><h1>Resultat</h1><p><?=e($quiz['title'])?></p></div></header>
<section class="results-layout"><aside class="result-sessions"><?php if(!$games):?><p>Inga spel har körts ännu.</p><?php endif;foreach($games as $game):?><article class="result-session <?=($selected&&$game['id']===$selected['id'])?'active':''?>"><a class="result-session-link" href="results.php?quiz=<?=$quizId?>&game=<?=$game['id']?>"><strong><?=e($game['name']?:result_date($game['created_at']))?></strong><small><?=e(result_date($game['created_at']))?> · <?=$game['players']?> deltagare · <?=e($game['status']==='finished'?'Avslutad':'Ej avslutad')?></small></a><details class="session-actions"><summary>Hantera</summary><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="rename_session"><input type="hidden" name="game_id" value="<?=$game['id']?>"><input name="name" value="<?=e($game['name'])?>" maxlength="140" placeholder="Namn på sessionen"><button>Spara namn</button></form><form method="post" onsubmit="return confirm('Ta bort sessionen och alla dess resultat? Det går inte att ångra.')"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="delete_session"><input type="hidden" name="game_id" value="<?=$game['id']?>"><button class="danger">Ta bort session</button></form></details></article><?php endforeach?></aside>
<?php if($selected):?><div class="results-panel"><div class="result-heading"><div><h2><?=e($selected['name']?:$quiz['title'])?></h2><p><?php if($selected['name']):?><?=e($quiz['title'])?> · <?php endif?><?=e(result_date($selected['created_at']))?> · <?=$selected['players']?> deltagare</p></div><button type="button" class="print-button" onclick="window.print()">Skriv ut resultatblad</button></div><?php if(!$players):?><p>Inga deltagare anslöt till detta spel.</p><?php else:?><table class="results-table"><thead><tr><th>Alias</th><?php foreach($questions as $q):?><th title="<?=e($q['text'])?>">Fråga <?=$q['position']?></th><?php endforeach?><th>Totalt</th></tr></thead><tbody><?php foreach($players as $player):?><tr><th><?=e($player['name'])?></th><?php foreach($questions as $q):?><td><?=isset($points[(int)$player['id']][(int)$q['question_id']])?$points[(int)$player['id']][(int)$q['question_id']].' p':'—'?></td><?php endforeach?><td class="total"><?=(int)$player['score']?> p</td></tr><?php endforeach?></tbody></table><h3>Frågor</h3><ol><?php foreach($questions as $q):?><li><?=e($q['text'])?> <small>(max <?=(int)$q['max_points']?> p)</small></li><?php endforeach?></ol><?php endif?></div><?php endif?></section>
<?php page_bottom();?>
